from enroll.models import Student
def studentinfo(request):
    stud = Student.objects.all()
    return render(request, 'enroll/studetails.html', {'stu': stud})

Template:
{% for st in stu %} {{st.stuname}} {% endfor %}

def __str__(self):
    return self.stuname
Shows a readable name for each record in the admin instead of 'Student object (1)'.

if request.method == 'POST':
    fm = StudentRegistration(request.POST)
    if fm.is_valid():
        print(fm.cleaned_data['name'])
is_valid() runs validation; cleaned_data holds the safe values.

def clean_name(self):
    value = self.cleaned_data['name']
    if len(value) < 4:
        raise forms.ValidationError('Enter 4 or more characters')
    return value
Method name must be clean_<fieldname>.

def clean(self):
    cleaned_data = super().clean()
    if cleaned_data['password'] != cleaned_data['rpassword']:
        raise forms.ValidationError('Password does not match')
Use clean() to compare two fields.
